1	import { GameEngine } from "@/lib/game/engine/GameEngine";
2	import type { Command } from "@/lib/game/engine/commands";
3	import { createFixedTicker, TICK_SECONDS, type FixedTicker } from "@/lib/game/engine/tickDriver";
4	import {
5	  serializeEffects,
6	  serializeEquippedArmor,
7	  inventorySlotsSnapshot,
8	  serializeMobs,
9	  serializeVehicles,
10	  serializeContainers,
11	  serializeLootedChests
12	} from "@/lib/game/save";
13	import type { SavedPlayer } from "@/lib/game/types";
14	import type { PlayerState } from "@/lib/game/engine/state";
15	import { encodeServerMessage, gzipWorldSync } from "@/lib/net/codec";
16	import {
17	  CLOSE_KICKED,
18	  CLOSE_ROOM_FULL,
19	  CLOSE_SERVER_SHUTDOWN,
20	  CLOSE_SLOW_CLIENT,
21	  PROTOCOL_VERSION,
22	  ROOM_CAPACITY,
23	  type ClientMessage,
24	  type MobPose,
25	  type PlayerPose,
26	  type RosterEntry,
27	  type SelfDelta,
28	  type ServerMessage,
29	  type TickMessage,
30	  type WorldSync
31	} from "@/lib/net/protocol";
32	import type { TicketClaims } from "@/lib/net/tickets";
33	import type { Persistence, WorldRecord } from "./persistence";
34	
35	/**
36	 * One world room: an authoritative GameEngine on the fixed 20 Hz ticker,
37	 * fed by client poses/commands and broadcasting per-tick deltas. Sockets are
38	 * abstracted as ClientSink so the whole class unit-tests with fakes; only
39	 * index.ts binds it to real Bun WebSockets.
40	 */
41	
42	export type ClientSink = {
43	  send(data: string | Uint8Array): void;
44	  close(code: number, reason?: string): void;
45	  bufferedAmount(): number;
46	};
47	
48	type ClientConn = {
49	  playerId: string;
50	  name: string;
51	  skinId: string | null;
52	  role: "owner" | "member";
53	  sink: ClientSink;
54	  /** Highest pose seq applied (stale/replayed packets drop). */
55	  poseSeq: number;
56	  /** Tick of the last accepted pose (drives the clamp's elapsed time). */
57	  lastPoseTick: number;
58	  /** Per-second message budgets (reset each second-boundary tick). */
59	  budget: { cmd: number; chat: number };
60	  /** Sustained-backpressure strikes toward a slow-client kick. */
61	  slowStrikes: number;
62	  /** Shadow of the last self-delta sent (reference/primitive compares). */
63	  shadow: {
64	    inventory: unknown;
65	    equippedArmor: unknown;
66	    selectedSlot: number;
67	    hearts: number;
68	    hunger: number;
69	    oxygen: number;
70	    xp: number;
71	    isDead: boolean;
72	    respawnSeconds: number;
73	    gameMode: string;
74	    sleeping: boolean;
75	    effectsKey: string;
76	  } | null;
77	};
78	
79	const PERSIST_INTERVAL_TICKS = 20 * 60; // 60s
80	const KEYFRAME_INTERVAL_TICKS = 20 * 5; // 5s
81	const DAY_INTERVAL_TICKS = 20; // 1s
82	const POSE_CHECKPOINT_TICKS = 20; // 1s — log pose anchors between commands
83	const MOB_DEADBAND_SQ = 0.05 * 0.05;
84	const BACKPRESSURE_SOFT_BYTES = 256 * 1024;
85	const BACKPRESSURE_KICK_BYTES = 1024 * 1024;
86	const BACKPRESSURE_KICK_STRIKES = 100; // ~5s of sustained >1MB at 20Hz
87	const DEFAULT_COMMAND_LOG_SIZE = 4096;
88	
89	/** One entry in a room's replay log: a dispatched command (with its claimed eye pose) or a periodic pose anchor. */
90	export type CommandLogEntry =
91	  | { tick: number; playerId: string; cmd: Command; pose: { x: number; y: number; z: number; yaw: number; pitch: number } }
92	  | { tick: number; playerId: string; pose: { x: number; y: number; z: number; yaw: number; pitch: number } };
93	
94	/** A room's replay log plus the world constants needed to reconstruct it offline (see server/scripts/replay.ts). */
95	export type RoomLogDump = {
96	  worldId: string;
97	  seed: number;
98	  worldType: string;
99	  difficulty: string;
100	  hardcore: boolean;
101	  tick: number;
102	  entries: CommandLogEntry[];
103	};
104	
105	export class Room {
106	  readonly worldId: string;
107	  readonly engine: GameEngine;
108	  private readonly clients = new Map<string, ClientConn>();
109	  /** Persisted slices of players who left (merged into the stored save). */
110	  private readonly offlinePlayers = new Map<string, SavedPlayer>();
111	  private readonly persistence: Persistence;
112	  private ticker: FixedTicker | null = null;
113	  private tickCount = 0;
114	  private dirtySinceStore = false;
115	  private readonly mobShadow = new Map<number, { x: number; y: number; z: number; hp: number }>();
116	  /** Wall-clock ms when the room became empty (idle-eviction clock), or null while occupied. */
117	  emptySinceMs: number | null;
118	  /** p95-ish diagnostics: the slowest tick of the last window. */
119	  private slowestTickMs = 0;
120	  /** Total bytes sent downstream (monotonic); diagnostics reports the delta since its last read. */
121	  private bytesOut = 0;
122	  private lastDiagBytes = 0;
123	  private lastDiagTick = 0;
124	  /** Rolling replay log: recent commands + pose anchors (ring-bounded). */
125	  private readonly commandLog: CommandLogEntry[] = [];
126	  private readonly commandLogSize: number;
127	
128	  constructor(
129	    record: WorldRecord,
130	    persistence: Persistence,
131	    private readonly now: () => number = () => Date.now(),
132	    commandLogSize = Number.parseInt(process.env.COMMAND_LOG_SIZE ?? "", 10) || DEFAULT_COMMAND_LOG_SIZE
133	  ) {
134	    this.worldId = record.id;
135	    this.persistence = persistence;
136	    this.commandLogSize = commandLogSize;
137	    this.engine = new GameEngine({
138	      save: record.save,
139	      seed: record.seed,
140	      worldType: record.worldType as never,
141	      difficulty: record.difficulty as never,
142	      hardcore: record.hardcore,
143	      authority: "server",
144	      headless: true,
145	      bootPlayer: false
146	    });
147	    for (const saved of record.save?.players ?? []) this.offlinePlayers.set(saved.id, saved);
148	    this.emptySinceMs = this.now();
149	  }
150	
151	  /** Starts the 20 Hz ticker (index.ts calls this once after construction). */
152	  start(setTimer?: (fn: () => void, ms: number) => ReturnType<typeof setTimeout>, clearTimer?: (id: ReturnType<typeof setTimeout>) => void): void {
153	    this.ticker = createFixedTicker({
154	      onTick: (dt) => this.tick(dt),
155	      now: () => this.now(),
156	      ...(setTimer ? { setTimer } : {}),
157	      ...(clearTimer ? { clearTimer } : {})
158	    });
159	  }
160	
161	  playerCount(): number {
162	    return this.clients.size;
163	  }
164	
165	  diagnostics(): { worldId: string; players: number; tick: number; slowestTickMs: number; kbOutPerSec: number } {
166	    // Bandwidth over the window since the last read (not a lifetime average).
167	    const windowTicks = Math.max(1, this.tickCount - this.lastDiagTick);
168	    const windowBytes = this.bytesOut - this.lastDiagBytes;
169	    this.lastDiagTick = this.tickCount;
170	    this.lastDiagBytes = this.bytesOut;
171	    return {
172	      worldId: this.worldId,
173	      players: this.clients.size,
174	      tick: this.tickCount,
175	      slowestTickMs: Math.round(this.slowestTickMs * 100) / 100,
176	      kbOutPerSec: Math.round((windowBytes / 1024 / (windowTicks * TICK_SECONDS)) * 10) / 10
177	    };
178	  }
179	
180	  /** The replay log + world constants (admin-only; drives server/scripts/replay.ts). */
181	  logDump(): RoomLogDump {
182	    return {
183	      worldId: this.worldId,
184	      seed: this.engine.state.world.seed,
185	      worldType: this.engine.worldTypeName,
186	      difficulty: this.engine.state.difficulty,
187	      hardcore: this.engine.state.hardcore,
188	      tick: this.tickCount,
189	      entries: [...this.commandLog]
190	    };
191	  }
192	
193	  private recordLog(entry: CommandLogEntry): void {
194	    this.commandLog.push(entry);
195	    if (this.commandLog.length > this.commandLogSize) this.commandLog.splice(0, this.commandLog.length - this.commandLogSize);
196	  }
197	
198	  /** Admits a verified ticket onto a socket: joins the engine and syncs the world. */
199	  async join(claims: TicketClaims, sink: ClientSink): Promise<boolean> {
200	    // A reconnecting member already owns a slot — only a genuinely NEW player
201	    // counts against capacity, so a dropped socket can always come back.
202	    const reconnecting = this.clients.has(claims.sub);
203	    if (!reconnecting && this.clients.size >= ROOM_CAPACITY) {
204	      sink.close(CLOSE_ROOM_FULL, "room full");
205	      return false;
206	    }
207	    // A reconnect replaces the old socket (the stale one is closed silently).
208	    this.clients.get(claims.sub)?.sink.close(CLOSE_KICKED, "replaced by a new connection");
209	    this.clients.delete(claims.sub);
210	
211	    const restore = this.offlinePlayers.get(claims.sub) ?? null;
212	    const player = this.engine.addPlayer({ id: claims.sub, restore });
213	    this.offlinePlayers.delete(claims.sub);
214	    this.dirtySinceStore = true;
215	
216	    const conn: ClientConn = {
217	      playerId: claims.sub,
218	      name: claims.name,
219	      skinId: claims.skinId,
220	      role: claims.role,
221	      sink,
222	      poseSeq: -1,
223	      lastPoseTick: this.tickCount,
224	      budget: { cmd: 0, chat: 0 },
225	      slowStrikes: 0,
226	      shadow: null
227	    };
228	    this.clients.set(claims.sub, conn);
229	    this.emptySinceMs = null;
230	
231	    sink.send(
232	      encodeServerMessage({
233	        t: "welcome",
234	        protocol: PROTOCOL_VERSION,
235	        playerId: claims.sub,
236	        worldId: this.worldId,
237	        seed: this.engine.state.world.seed,
238	        worldType: this.engine.worldTypeName,
239	        difficulty: this.engine.state.difficulty,
240	        hardcore: this.engine.state.hardcore,
241	        dayClock: this.engine.state.dayClock,
242	        tick: this.tickCount,
243	        players: this.roster()
244	      })
245	    );
246	    sink.send(await gzipWorldSync(this.buildWorldSync()));
247	    this.broadcast({ t: "playerJoined", player: this.rosterEntry(player, conn) }, claims.sub);
248	    return true;
249	  }
250	
251	  /** Owner-initiated eject: close the socket with a fatal code so the client won't retry, then leave. Returns false if not present. */
252	  kick(playerId: string): boolean {
253	    const conn = this.clients.get(playerId);
254	    if (!conn) return false;
255	    conn.sink.close(CLOSE_KICKED, "removed by the world owner");
256	    this.leave(playerId);
257	    return true;
258	  }
259	
260	  /** Removes a player (socket closed or kicked); persists their slice into the offline set. */
261	  leave(playerId: string): void {
262	    const conn = this.clients.get(playerId);
263	    if (!conn) return;
264	    this.clients.delete(playerId);
265	    const saved = this.engine.removePlayer(playerId);
266	    if (saved) this.offlinePlayers.set(playerId, saved);
267	    this.dirtySinceStore = true;
268	    this.broadcast({ t: "playerLeft", id: playerId });
269	    if (this.clients.size === 0) this.emptySinceMs = this.now();
270	  }
271	
272	  /** One validated client frame. */
273	  async handleMessage(playerId: string, message: ClientMessage): Promise<void> {
274	    const conn = this.clients.get(playerId);
275	    if (!conn) return;
276	    switch (message.t) {
277	      case "pose": {
278	        if (message.seq <= conn.poseSeq) return; // stale or replayed
279	        conn.poseSeq = message.seq;
280	        const elapsed = Math.max(1, this.tickCount - conn.lastPoseTick) * TICK_SECONDS;
281	        const { accepted } = this.engine.applyRemotePose(playerId, message, elapsed);
282	        this.engine.setPlayerInput(playerId, { move: message.move, mineHeld: message.mineHeld });
283	        if (accepted) {
284	          conn.lastPoseTick = this.tickCount;
285	        } else {
286	          const player = this.engine.state.players.get(playerId);
287	          if (player) {
288	            conn.sink.send(
289	              encodeServerMessage({
290	                t: "forcePose",
291	                x: player.position.x,
292	                y: player.position.y,
293	                z: player.position.z,
294	                yaw: player.yaw,
295	                pitch: player.pitch
296	              })
297	            );
298	          }
299	        }
300	        return;
301	      }
302	      case "cmd": {
303	        if (conn.budget.cmd >= 60) return; // per-second flood guard
304	        conn.budget.cmd += 1;
305	        // Room-wide settings are the owner's call, not any member's.
306	        if ((message.cmd.type === "setDifficulty" || message.cmd.type === "setGameMode") && conn.role !== "owner") return;
307	        // Apply the claimed pose (same clamps as the stream) so the command's
308	        // raycast happens from where the client actually stood/aimed.
309	        const elapsed = Math.max(1, this.tickCount - conn.lastPoseTick) * TICK_SECONDS;
310	        const { accepted } = this.engine.applyRemotePose(
311	          playerId,
312	          { ...message.pose, onGround: this.engine.state.players.get(playerId)?.onGround ?? false },
313	          elapsed
314	        );
315	        // Advance the pose clock on an accepted cmd pose too — otherwise a
316	        // client sending only cmds lets `elapsed` grow and inflate the clamp.
317	        if (accepted) conn.lastPoseTick = this.tickCount;
318	        this.recordLog({ tick: this.tickCount, playerId, cmd: message.cmd, pose: message.pose });
319	        this.engine.dispatch(message.cmd, playerId);
320	        return;
321	      }
322	      case "chat": {
323	        if (conn.budget.chat >= 3) return;
324	        conn.budget.chat += 1;
325	        this.broadcast({ t: "chat", from: playerId, name: conn.name, text: message.text });
326	        return;
327	      }
328	      case "ping": {
329	        conn.sink.send(encodeServerMessage({ t: "pong", id: message.id, tMs: message.tMs, serverTick: this.tickCount }));
330	        return;
331	      }
332	      case "resync": {
333	        conn.sink.send(await gzipWorldSync(this.buildWorldSync()));
334	        conn.shadow = null; // resend the full self-delta next tick
335	        return;
336	      }
337	      case "hello":
338	        return; // already admitted; ignore
339	    }
340	  }
341	
342	  /** Drains the room for shutdown: persist + close every socket. */
343	  async shutdown(): Promise<void> {
344	    this.ticker?.stop();
345	    for (const conn of this.clients.values()) conn.sink.close(CLOSE_SERVER_SHUTDOWN, "server restarting");
346	    for (const playerId of [...this.clients.keys()]) this.leave(playerId);
347	    await this.persist();
348	  }
349	
350	  /** Persists the full world (live players merged with offline slices). */
351	  async persist(): Promise<void> {
352	    const save = this.engine.serialize();
353	    for (const [id, saved] of this.offlinePlayers) {
354	      if (!save.players.some((p) => p.id === id)) save.players.push(saved);
355	    }
356	    const bun = Bun as unknown as { gzipSync(d: Uint8Array): Uint8Array };
357	    const blob = bun.gzipSync(new TextEncoder().encode(JSON.stringify(save)));
358	    await this.persistence.storeWorld(this.worldId, blob, save.version);
359	    this.dirtySinceStore = false;
360	  }
361	
362	  // ── internals ──────────────────────────────────────────────────────────────
363	
364	  private tick(dt: number): void {
365	    const started = this.now();
366	    this.tickCount += 1;
367	    if (this.tickCount % 20 === 0) {
368	      for (const conn of this.clients.values()) conn.budget = { cmd: 0, chat: 0 };
369	    }
370	
371	    this.engine.step(dt);
372	    const events = this.engine.consumeEvents();
373	    const blocks = this.engine.state.blockChanges.drainEdits();
374	    if (events.some((e) => e.type === "blockPlaced" || e.type === "blockBroken" || e.type === "explosion")) this.dirtySinceStore = true;
375	
376	    const mobPoses = this.collectMobPoses(false);
377	    const day = this.tickCount % DAY_INTERVAL_TICKS === 0 ? this.engine.state.dayClock : undefined;
378	
379	    for (const conn of this.clients.values()) {
380	      const buffered = conn.sink.bufferedAmount();
381	      if (buffered > BACKPRESSURE_KICK_BYTES) {
382	        conn.slowStrikes += 1;
383	        if (conn.slowStrikes > BACKPRESSURE_KICK_STRIKES) {
384	          conn.sink.close(CLOSE_SLOW_CLIENT, "client cannot keep up");
385	          this.leave(conn.playerId);
386	        }
387	        continue;
388	      }
389	      conn.slowStrikes = 0;
390	      const shed = buffered > BACKPRESSURE_SOFT_BYTES;
391	      const message: TickMessage = {
392	        t: "tick",
393	        n: this.tickCount,
394	        ...(blocks.length > 0 ? { blocks } : {}),
395	        ev: events,
396	        pp: shed ? [] : this.collectPlayerPoses(conn.playerId),
397	        mp: shed ? [] : mobPoses,
398	        ...(day !== undefined ? { day } : {}),
399	        ...(this.buildSelfDelta(conn) ?? {})
400	      };
401	      const encoded = encodeServerMessage(message);
402	      this.bytesOut += encoded.length;
403	      conn.sink.send(encoded);
404	    }
405	
406	    // Pose anchors between commands keep an offline replay's positions aligned.
407	    if (this.tickCount % POSE_CHECKPOINT_TICKS === 0) {
408	      for (const player of this.engine.state.players.values()) {
409	        this.recordLog({
410	          tick: this.tickCount,
411	          playerId: player.id,
412	          pose: { x: player.position.x, y: player.position.y, z: player.position.z, yaw: player.yaw, pitch: player.pitch }
413	        });
414	      }
415	    }
416	
417	    if (this.tickCount % KEYFRAME_INTERVAL_TICKS === 0 && this.clients.size > 0) {
418	      this.broadcast({ t: "mobsKeyframe", n: this.tickCount, mobs: this.collectMobPoses(true) });
419	    }
420	    if (this.tickCount % PERSIST_INTERVAL_TICKS === 0 && this.dirtySinceStore) {
421	      void this.persist();
422	    }
423	    this.slowestTickMs = Math.max(this.slowestTickMs * 0.99, this.now() - started);
424	  }
425	
426	  private roster(): RosterEntry[] {
427	    const out: RosterEntry[] = [];
428	    for (const conn of this.clients.values()) {
429	      const player = this.engine.state.players.get(conn.playerId);
430	      if (player) out.push(this.rosterEntry(player, conn));
431	    }
432	    return out;
433	  }
434	
435	  private rosterEntry(player: PlayerState, conn: ClientConn): RosterEntry {
436	    return {
437	      id: player.id,
438	      name: conn.name,
439	      skinId: conn.skinId,
440	      x: player.position.x,
441	      y: player.position.y,
442	      z: player.position.z,
443	      yaw: player.yaw
444	    };
445	  }
446	
447	  private buildWorldSync(): WorldSync {
448	    const state = this.engine.state;
449	    return {
450	      t: "worldSync",
451	      tick: this.tickCount,
452	      dayClock: state.dayClock,
453	      changes: state.blockChanges.changes(),
454	      blockEntities: serializeContainers(state.containers),
455	      lootedChests: serializeLootedChests(state.lootedWorldgenChests),
456	      mobs: serializeMobs(state.mobs),
457	      liveMobs: this.collectMobPoses(true),
458	      vehicles: serializeVehicles(state.vehicles),
459	      players: this.roster()
460	    };
461	  }
462	
463	  private collectPlayerPoses(except: string): PlayerPose[] {
464	    const out: PlayerPose[] = [];
465	    for (const player of this.engine.state.players.values()) {
466	      if (player.id === except) continue;
467	      out.push({ id: player.id, x: player.position.x, y: player.position.y, z: player.position.z, yaw: player.yaw, pitch: player.pitch });
468	    }
469	    return out;
470	  }
471	
472	  private collectMobPoses(keyframe: boolean): MobPose[] {
473	    const out: MobPose[] = [];
474	    for (const mob of this.engine.state.mobs) {
475	      const shadow = this.mobShadow.get(mob.id);
476	      const moved =
477	        !shadow ||
478	        (mob.position.x - shadow.x) ** 2 + (mob.position.y - shadow.y) ** 2 + (mob.position.z - shadow.z) ** 2 > MOB_DEADBAND_SQ ||
479	        mob.hp !== shadow.hp;
480	      // Delta frames go at half rate (10 Hz) — keyframes always carry everything.
481	      if (!keyframe && (!moved || this.tickCount % 2 !== 0)) continue;
482	      this.mobShadow.set(mob.id, { x: mob.position.x, y: mob.position.y, z: mob.position.z, hp: mob.hp });
483	      out.push({
484	        id: mob.id,
485	        kind: mob.kind,
486	        hostile: mob.hostile,
487	        x: mob.position.x,
488	        y: mob.position.y,
489	        z: mob.position.z,
490	        yaw: mob.yaw,
491	        hp: mob.hp,
492	        moveSpeed: mob.moveSpeed
493	      });
494	    }
495	    if (keyframe) {
496	      const alive = new Set(this.engine.state.mobs.map((m) => m.id));
497	      for (const id of this.mobShadow.keys()) if (!alive.has(id)) this.mobShadow.delete(id);
498	    }
499	    return out;
500	  }
501	
502	  private buildSelfDelta(conn: ClientConn): { self: SelfDelta } | null {
503	    const player = this.engine.state.players.get(conn.playerId);
504	    if (!player) return null;
505	    const effectsKey = JSON.stringify(serializeEffects(player.effects));
506	    const respawnSeconds = Math.ceil(player.respawnTimer);
507	    const previous = conn.shadow;
508	    const delta: SelfDelta = {};
509	    if (!previous || previous.inventory !== player.inventory) delta.inventorySlots = inventorySlotsSnapshot(player.inventory);
510	    if (!previous || previous.equippedArmor !== player.equippedArmor) delta.equippedArmor = serializeEquippedArmor(player.equippedArmor);
511	    if (!previous || previous.selectedSlot !== player.selectedSlot) delta.selectedSlot = player.selectedSlot;
512	    if (!previous || previous.hearts !== player.hearts) delta.hearts = player.hearts;
