27	/**
28	 * The client end of a multiplayer world: owns the WebSocket and a REPLICA
29	 * engine the existing renderer/audio/HUD consume unchanged. Outbound, it
30	 * streams the local player's pose at tick rate and routes commands — local
31	 * presentation stays on the replica, gameplay goes to the server (selectSlot
32	 * optimistically does both). Inbound, it applies the server's block journal,
33	 * replays events into the shell's existing event drain, feeds pose buffers
34	 * for ~125 ms-delayed interpolation, and overwrites the local player's
35	 * private state from self-deltas (the server owns your vitals).
36	 *
37	 * The engine outlives the socket: a dropped connection (anything but a fatal
38	 * close — a bad ticket, a kick, a slow-client shed) runs a reconnect ladder
39	 * that mints a fresh ticket and redoes the handshake, re-syncing the same
40	 * replica in place — the player sees a brief "reconnecting" badge, not a
41	 * dead world.
42	 */
43	
44	export type NetStatus = "connecting" | "syncing" | "online" | "reconnecting" | "closed";
45	
46	/** A fresh place to connect: the reconnect ladder calls this to re-mint a ticket. */
47	export type JoinGrant = { url: string; ticket: string };
48	
49	export type NetworkSessionCallbacks = {
50	  onStatus?(status: NetStatus, detail?: string): void;
51	  onChat?(entry: { from: string; name: string; text: string }): void;
52	  /** Server events the shell's drain should also see (toasts, audio, particles). */
53	  onEvent?(event: GameEvent): void;
54	};
55	
56	export type NetworkSessionOptions = {
57	  /** Socket factory (tests inject a fake). */
58	  makeSocket?: (url: string) => WebSocket;
59	  /** Re-mint a ticket for the reconnect ladder; omit to disable reconnection. */
60	  reconnect?: () => Promise<JoinGrant | null>;
61	  /** Artificial round-trip delay (ms) for local latency testing; overridable at runtime. */
62	  simulatedLatencyMs?: number;
63	  /** Replica world footprint — tests shrink it; production must match the server's (default). */
64	  worldSize?: { x: number; y: number; z: number };
65	};
66	
67	/** Closes we don't retry: the door said no, or we'd just be kicked again. */
68	const FATAL_CLOSES = new Set<number>([CLOSE_BAD_TICKET, CLOSE_PROTOCOL_MISMATCH, CLOSE_ROOM_FULL, CLOSE_KICKED, CLOSE_SLOW_CLIENT]);
69	
70	/** Commands that never leave the client: pure presentation on the replica. */
71	const LOCAL_COMMANDS = new Set<Command["type"]>(["toggleInventory", "toggleAdvancements", "toggleDebug", "toggleCameraView", "pause", "resume"]);
72	
73	const HANDSHAKE_TIMEOUT_MS = 15000;
74	
75	export type NetworkSession = {
76	  readonly engine: GameEngine;
77	  readonly playerId: PlayerId;
78	  /** UI subscriptions (React components mount after connect; unsubscribe on cleanup). */
79	  subscribeChat(listener: (entry: { from: string; name: string; text: string }) => void): () => void;
80	  subscribeStatus(listener: (status: NetStatus) => void): () => void;
81	  status(): NetStatus;
82	  rttMs(): number;
83	  /** Names for remote player ids (name tags, chat). */
84	  playerName(id: PlayerId): string;
85	  dispatch(command: Command): void;
86	  applyLook(deltaYaw: number, deltaPitch: number): void;
87	  sendChat(text: string): void;
88	  /** Debug knob: inject symmetric latency on every send/receive (0 disables). */
89	  setSimulatedLatency(ms: number): void;
90	  simulatedLatency(): number;
91	  /** Server events since the last drain — feed the shell's existing event handler. */
92	  drainEvents(): GameEvent[];
93	  /** Call once per rAF after engine.step: flushes the pose stream and samples interpolation. */
94	  afterFrame(nowMs: number): void;
95	  dispose(): void;
96	};
97	
98	export async function connectNetworkSession(
99	  url: string,
100	  ticket: string,
101	  callbacks: NetworkSessionCallbacks = {},
102	  options: NetworkSessionOptions = {}
103	): Promise<NetworkSession> {
104	  const makeSocket = options.makeSocket ?? ((u: string) => new WebSocket(u));
105	  const envLatency = Number.parseInt(process.env.NEXT_PUBLIC_NET_SIM_LATENCY_MS ?? "", 10);
106	  let simulatedLatencyMs = options.simulatedLatencyMs ?? (Number.isFinite(envLatency) ? envLatency : 0);
107	
108	  let status: NetStatus = "connecting";
109	  let disposed = false;
110	  let ws: WebSocket | null = null;
111	  const chatListeners = new Set<(entry: { from: string; name: string; text: string }) => void>();
112	  const statusListeners = new Set<(status: NetStatus) => void>();
113	  const setStatus = (next: NetStatus, detail?: string) => {
114	    status = next;
115	    callbacks.onStatus?.(next, detail);
116	    for (const listener of statusListeners) listener(next);
117	  };
118	
119	  const clock = createClockSync();
120	  const pendingEvents: GameEvent[] = [];
121	  const playerBuffers = new Map<string, PoseBuffer>();
122	  const mobBuffers = new Map<number, PoseBuffer>();
123	  const names = new Map<string, string>();
124	  let serverTickTimeMs = 0;
125	
126	  // Latency simulation wraps both directions symmetrically so `ms` reads as a
127	  // one-way delay (round-trip ≈ 2×ms), matching how a player would set it.
128	  const delayedSend = (data: string) => {
129	    const socket = ws;
130	    if (!socket || socket.readyState !== WebSocket.OPEN) return;
131	    if (simulatedLatencyMs > 0) {
132	      setTimeout(() => {
133	        try {
134	          if (socket.readyState === WebSocket.OPEN) socket.send(data);
135	        } catch {
136	          /* socket closed under us */
137	        }
138	      }, simulatedLatencyMs);
139	      return;
140	    }
141	    socket.send(data);
142	  };
143	
144	  // ── handshake: open a socket, send hello, await welcome ─────────────────────
145	  const handshake = (currentTicket: string, serverUrl: string): Promise<WelcomeMessage> =>
146	    new Promise<WelcomeMessage>((resolve, reject) => {
147	      const socket = makeSocket(`${serverUrl.replace(/\/$/, "")}/ws`);
148	      socket.binaryType = "arraybuffer";
149	      ws = socket;
150	      const timer = setTimeout(() => {
151	        reject(new Error("join timed out"));
152	        try {
153	          socket.close();
154	        } catch {
155	          /* already closing */
156	        }
157	      }, HANDSHAKE_TIMEOUT_MS);
158	      socket.onopen = () => socket.send(encodeClientMessage({ t: "hello", ticket: currentTicket, protocol: PROTOCOL_VERSION }));
159	      socket.onerror = () => reject(new Error("connection failed"));
160	      socket.onclose = (event) => reject(new Error(`refused: ${event.code} ${event.reason}`));
161	      socket.onmessage = (event) => {
162	        const message = decodeServerFrame(event.data);
163	        if (message?.t === "welcome") {
164	          clearTimeout(timer);
165	          // Hand the socket over to the steady-state handlers.
166	          socket.onmessage = (frame) => onServerFrame(frame.data);
167	          socket.onclose = (frame) => onSocketClosed(frame.code, frame.reason);
168	          socket.onerror = () => onSocketClosed(1006, "socket error");
169	          resolve(message);
170	        }
171	      };
172	    });
173	
174	  const welcome = await handshake(ticket, url);
175	  setStatus("syncing");
176	
177	  // The replica: an empty mirror world generated from the server's seed.
178	  const engine = new GameEngine({
179	    seed: welcome.seed,
180	    worldType: welcome.worldType as never,
181	    difficulty: welcome.difficulty as never,
182	    hardcore: welcome.hardcore,
183	    authority: "local",
184	    replica: true,
185	    bootPlayer: false,
186	    ...(options.worldSize ? { worldSize: options.worldSize } : {})
187	  });
188	  const state = engine.state;
189	  const playerId = welcome.playerId;
190	  state.dayClock = welcome.dayClock;
191	  state.primaryPlayerId = playerId;
192	  const self = engine.addPlayer({ id: playerId });
193	  self.input = createIdleInput();
194	  engine.consumeEvents(); // drop the join echo
195	  serverTickTimeMs = welcome.tick * TICK_SECONDS * 1000;
196	
197	  // Every dispatch from the UI/input controller routes here (see
198	  // GameEngine.routeDispatch): presentation stays local, gameplay goes up.
199	  engine.routeDispatch = (command) => {
200	    if (LOCAL_COMMANDS.has(command.type)) {
201	      engine.dispatch(command, playerId);
202	      return;
203	    }
204	    if (command.type === "selectSlot") engine.dispatch(command, playerId); // optimistic
205	    sendCmd(command);
206	  };
207	
208	  const upsertRemotePlayer = (id: string, name: string) => {
209	    names.set(id, name);
210	    if (id === playerId || state.players.has(id)) return;
211	    engine.addPlayer({ id });
212	    engine.consumeEvents();
213	  };
214	
215	  const applyRoster = (roster: WelcomeMessage["players"]) => {
216	    for (const entry of roster) upsertRemotePlayer(entry.id, entry.name);
217	    const present = new Set(roster.map((entry) => entry.id));
218	    // Anyone who left while we were away is no longer in the roster.
219	    for (const id of [...state.players.keys()]) {
220	      if (id === playerId || present.has(id)) continue;
221	      engine.removePlayer(id);
222	      engine.consumeEvents();
223	      playerBuffers.delete(id);
224	    }
225	  };
226	
227	  for (const entry of welcome.players) upsertRemotePlayer(entry.id, entry.name);
228	  const myRoster = welcome.players.find((entry) => entry.id === playerId);
229	  if (myRoster) self.position.set(myRoster.x, myRoster.y, myRoster.z);
230	
231	  const applyWorldSync = (sync: WorldSync) => {
232	    state.blockChanges.applySavedChanges(sync.changes);
233	    state.worldMeshDirty = true;
234	    state.dayClock = sync.dayClock;
235	    serverTickTimeMs = sync.tick * TICK_SECONDS * 1000;
236	    state.containers.clear();
237	    for (const entry of sync.blockEntities) {
238	      const restored = restoreInventorySlots({ id: "container", inventorySlots: entry.slots });
239	      if (restored) state.containers.set(entry.index, restored);
240	    }
241	    state.lootedWorldgenChests = new Set(sync.lootedChests);
242	    state.mobs = [];
243	    mobBuffers.clear();
244	    for (const pose of sync.liveMobs) upsertReplicaMob(pose);
245	    applyRoster(sync.players);
246	  };
247	
248	  function upsertReplicaMob(pose: MobPose): MobState {
249	    let mob = state.mobs.find((m) => m.id === pose.id);
250	    if (!mob) {
251	      const kind = (MOB_TEMPLATES[pose.kind as MobKind] ? pose.kind : "zombie") as MobKind;
252	      const template = MOB_TEMPLATES[kind];
253	      mob = {
254	        id: pose.id,
255	        kind,
256	        hostile: pose.hostile,
257	        faction: FACTION_BY_KIND[kind],
258	        targetId: null,
259	        retargetTimer: 0,
260	        hp: pose.hp,
261	        position: new THREE.Vector3(pose.x, pose.y, pose.z),
262	        direction: new THREE.Vector3(1, 0, 0),
263	        yaw: pose.yaw,
264	        turnTimer: 0,
265	        speed: template.speed,
266	        moveSpeed: pose.moveSpeed,
267	        detectRange: template.detectRange,
268	        attackDamage: 0,
269	        attackCooldown: 1,
270	        attackTimer: 0,
271	        halfHeight: mobHalfHeight(kind),
272	        bobSeed: pose.id * 0.7,
273	        fedTimer: 0,
274	        ageTimer: 0
275	      };
276	      state.mobs.push(mob);
277	    }
278	    mob.hp = pose.hp;
279	    mob.moveSpeed = pose.moveSpeed;
280	    let buffer = mobBuffers.get(pose.id);
281	    if (!buffer) {
282	      buffer = createPoseBuffer();
283	      mobBuffers.set(pose.id, buffer);
284	    }
285	    return mob;
286	  }
287	
288	  const applySelfDelta = (delta: SelfDelta) => {
289	    const shim = { id: self.id, ...delta };
290	    if (delta.inventorySlots) self.inventory = restoreInventorySlots(shim) ?? self.inventory;
291	    if (delta.equippedArmor) self.equippedArmor = restoreEquippedArmor(shim) ?? self.equippedArmor;
292	    if (delta.selectedSlot !== undefined) self.selectedSlot = restoreSelectedSlot(shim) ?? self.selectedSlot;
293	    if (delta.hearts !== undefined) self.hearts = delta.hearts;
294	    if (delta.hunger !== undefined) self.hunger = delta.hunger;
295	    if (delta.oxygen !== undefined) self.oxygen = delta.oxygen;
296	    if (delta.xp !== undefined) self.xp = delta.xp;
297	    if (delta.isDead !== undefined) self.isDead = delta.isDead;
298	    if (delta.respawnSeconds !== undefined) self.respawnTimer = delta.respawnSeconds;
299	    if (delta.gameMode !== undefined) self.gameMode = delta.gameMode as never;
300	    if (delta.sleeping !== undefined) self.sleeping = delta.sleeping;
301	    if (delta.effects) {
302	      self.effects.clear();
303	      for (const { id, remaining } of restoreEffects(shim)) self.effects.set(id, remaining);
304	    }
305	  };
306	
307	  const applyBlocks = (blocks: Array<[number, number]>) => {
308	    const layer = state.world.sizeX * state.world.sizeZ;
309	    for (const [idx, block] of blocks) {
310	      const y = Math.floor(idx / layer);
311	      const rem = idx - y * layer;
312	      const z = Math.floor(rem / state.world.sizeX);
313	      const x = rem - z * state.world.sizeX;
314	      state.blockChanges.set(x, y, z, block as never); // relights locally too
315	    }
316	    if (blocks.length > 0) state.worldMeshDirty = true;
317	  };
318	
319	  // ── inbound frame processing (latency-shifted) ──────────────────────────────
320	  const onServerFrame = (data: unknown) => {
321	    if (simulatedLatencyMs > 0) {
322	      setTimeout(() => void processServerFrame(data), simulatedLatencyMs);
323	      return;
324	    }
325	    void processServerFrame(data);
326	  };
327	
328	  async function processServerFrame(data: unknown): Promise<void> {
329	    if (typeof data !== "string") {
330	      const sync = await gunzipWorldSync(new Uint8Array(data as ArrayBuffer));
331	      if (sync) {
332	        applyWorldSync(sync);
333	        setStatus("online");
334	      }
335	      return;
336	    }
337	    const message = decodeServerFrame(data);
338	    if (!message) return;
339	    switch (message.t) {
340	      case "tick": {
341	        serverTickTimeMs = message.n * TICK_SECONDS * 1000;
342	        if (message.blocks) applyBlocks(message.blocks);
343	        if (message.day !== undefined) state.dayClock = message.day;
344	        if (message.self) applySelfDelta(message.self);
345	        for (const pose of message.pp) {
346	          upsertRemotePlayer(pose.id, names.get(pose.id) ?? "player");
347	          let buffer = playerBuffers.get(pose.id);
348	          if (!buffer) {
349	            buffer = createPoseBuffer();
350	            playerBuffers.set(pose.id, buffer);
351	          }
352	          buffer.push({ tMs: serverTickTimeMs, ...pose });
353	        }
354	        for (const pose of message.mp) {
355	          upsertReplicaMob(pose);
356	          mobBuffers.get(pose.id)?.push({ tMs: serverTickTimeMs, x: pose.x, y: pose.y, z: pose.z, yaw: pose.yaw });
357	        }
358	        for (const gameEvent of message.ev) {
359	          pendingEvents.push(gameEvent as GameEvent);
360	          callbacks.onEvent?.(gameEvent as GameEvent);
361	        }
362	        return;
363	      }
364	      case "mobsKeyframe": {
365	        const alive = new Set(message.mobs.map((m) => m.id));
366	        state.mobs = state.mobs.filter((m) => alive.has(m.id));
367	        for (const id of [...mobBuffers.keys()]) if (!alive.has(id)) mobBuffers.delete(id);
368	        const tMs = message.n * TICK_SECONDS * 1000;
369	        for (const pose of message.mobs) {
370	          upsertReplicaMob(pose);
371	          mobBuffers.get(pose.id)?.push({ tMs, x: pose.x, y: pose.y, z: pose.z, yaw: pose.yaw });
372	        }
373	        return;
374	      }
375	      case "playerJoined": {
376	        upsertRemotePlayer(message.player.id, message.player.name);
377	        const joined = state.players.get(message.player.id);
378	        joined?.position.set(message.player.x, message.player.y, message.player.z);
379	        return;
380	      }
381	      case "playerLeft": {
382	        if (message.id !== playerId) engine.removePlayer(message.id);
383	        playerBuffers.delete(message.id);
384	        engine.consumeEvents();
385	        return;
386	      }
387	      case "container": {
388	        const restored = restoreInventorySlots({ id: "container", inventorySlots: message.slots });
389	        if (restored) state.containers.set(message.index, restored);
390	        return;
391	      }
392	      case "chat":
393	        callbacks.onChat?.(message);
394	        for (const listener of chatListeners) listener(message);
395	        return;
396	      case "pong":
397	        clock.onPong(message.tMs, performance.now(), message.serverTick);
398	        return;
399	      case "forcePose":
400	        self.position.set(message.x, message.y, message.z);
401	        self.velocity.set(0, 0, 0);
402	        return;
403	      case "welcome":
404	        return;
405	    }
406	  }
407	
408	  // ── reconnect ladder ────────────────────────────────────────────────────────
409	  let reconnectAttempt = 0;
410	  let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
411	
412	  const onSocketClosed = (code: number, reason: string) => {
413	    if (disposed) return;
414	    if (FATAL_CLOSES.has(code) || !options.reconnect) {
415	      setStatus("closed", `${code} ${reason}`);
416	      return;
417	    }
418	    scheduleReconnect();
419	  };
420	
421	  const scheduleReconnect = () => {
422	    if (disposed) return;
423	    if (reconnectAttempt >= RECONNECT_DELAYS_MS.length) {
424	      setStatus("closed", "could not reconnect");
425	      return;
426	    }
427	    const delay = RECONNECT_DELAYS_MS[reconnectAttempt];
428	    reconnectAttempt += 1;
429	    setStatus("reconnecting", `attempt ${reconnectAttempt}`);
430	    reconnectTimer = setTimeout(() => void tryReconnectOnce(), delay);
431	  };
432	
433	  async function tryReconnectOnce(): Promise<void> {
434	    if (disposed || !options.reconnect) return;
435	    const grant = await options.reconnect();
436	    if (disposed) return;
437	    if (!grant) {
438	      scheduleReconnect();
439	      return;
440	    }
441	    try {
442	      const resumed = await handshake(grant.ticket, grant.url);
443	      if (disposed) return;
444	      // Same room, same id: keep the replica; the world-sync that follows
445	      // re-seeds it. Just refresh the roster and the server-time anchor.
446	      serverTickTimeMs = resumed.tick * TICK_SECONDS * 1000;
447	      applyRoster(resumed.players);
448	      reconnectAttempt = 0;
449	      setStatus("syncing");
450	    } catch {
451	      scheduleReconnect();
452	    }
453	  }
454	
455	  // ── outbound ────────────────────────────────────────────────────────────────
456	  let seq = 0;
457	  let lastPoseSentMs = 0;
458	  let lastPingMs = 0;
459	
460	  const sendCmd = (command: Command) => {
461	    seq += 1;
462	    // Foot position (matching the pose stream): the server clamps it into
463	    // player.position, then the engine derives the eye/aim ray from it by
464	    // adding EYE_HEIGHT — sending eye height here would double that offset.
465	    delayedSend(
466	      encodeClientMessage({
467	        t: "cmd",
468	        seq,
469	        cmd: command,
470	        pose: { x: self.position.x, y: self.position.y, z: self.position.z, yaw: self.yaw, pitch: self.pitch }
471	      })
472	    );
473	  };
474	
475	  const session: NetworkSession = {
476	    engine,
477	    playerId,
478	    subscribeChat(listener) {
479	      chatListeners.add(listener);
480	      return () => chatListeners.delete(listener);
481	    },
482	    subscribeStatus(listener) {
483	      statusListeners.add(listener);
484	      return () => statusListeners.delete(listener);
485	    },
486	    drainEvents: () => pendingEvents.splice(0, pendingEvents.length),
487	    status: () => status,
488	    rttMs: () => clock.rttMs(),
489	    playerName: (id) => names.get(id) ?? "player",
490	
491	    dispatch(command) {
492	      engine.dispatch(command); // routeDispatch handles the local/network split
493	    },
494	
495	    applyLook(deltaYaw, deltaPitch) {
496	      engine.applyLook(deltaYaw, deltaPitch);
497	    },
498	
499	    sendChat(text) {
500	      if (text.trim()) delayedSend(encodeClientMessage({ t: "chat", text: text.slice(0, 256) }));
501	    },
502	
503	    setSimulatedLatency(ms) {
504	      simulatedLatencyMs = Math.max(0, Math.floor(ms));
505	    },
506	    simulatedLatency: () => simulatedLatencyMs,
507	
508	    afterFrame(nowMs) {
509	      const open = ws?.readyState === WebSocket.OPEN;
510	      // Pose stream at tick rate.
511	      if (open && nowMs - lastPoseSentMs >= TICK_SECONDS * 1000) {
512	        lastPoseSentMs = nowMs;
513	        seq += 1;
514	        delayedSend(
515	          encodeClientMessage({
516	            t: "pose",
517	            seq,
518	            x: self.position.x,
519	            y: self.position.y,
520	            z: self.position.z,
521	            yaw: self.yaw,
522	            pitch: self.pitch,
523	            onGround: self.onGround,
524	            move: self.input.move,
525	            mineHeld: self.input.mineHeld
526	          })
527	        );
528	      }
529	      if (open && nowMs - lastPingMs >= 2000) {
530	        lastPingMs = nowMs;
531	        delayedSend(encodeClientMessage({ t: "ping", id: seq, tMs: nowMs }));
532	      }
533	      // Interpolation: remote entities render ~125ms in the past.
534	      const renderTime = (clock.ready() ? clock.estimatedServerTimeMs(nowMs) : serverTickTimeMs) - INTERPOLATION_DELAY_MS;
535	      for (const [id, buffer] of playerBuffers) {
536	        const player = state.players.get(id);
537	        const pose = buffer.sample(renderTime);
538	        if (player && pose) {
539	          player.position.set(pose.x, pose.y, pose.z);
540	          player.yaw = pose.yaw;
541	          player.pitch = pose.pitch;
542	        }
543	      }
544	      for (const [id, buffer] of mobBuffers) {
545	        const mob = state.mobs.find((m) => m.id === id);
546	        const pose = buffer.sample(renderTime);
547	        if (mob && pose) {
548	          mob.position.set(pose.x, pose.y, pose.z);
549	          mob.yaw = pose.yaw;
550	        }
551	      }
552	    },
553	
554	    dispose() {
555	      disposed = true;
556	      if (reconnectTimer) clearTimeout(reconnectTimer);
557	      setStatus("closed", "left world");
558	      try {
559	        ws?.close(1000, "leaving");
560	      } catch {
561	        /* already closed */
562	      }
563	    }
564	  };
565	  return session;
566	}
