  // Dismount: the server clears the mount and hands back a ground position.
  instances[0].emit(tick({ mountedVehicleId: null, x: 31, y: 40, z: 31 }));
  expect(self.mountedVehicleId).toBeNull();
  expect(self.position.x).toBe(31);
  session.dispose();
});

