150	  start(setTimer?: (fn: () => void, ms: number) => ReturnType<typeof setTimeout>, clearTimer?: (id: ReturnType<typeof setTimeout>) => void): void {
151	    this.ticker = createFixedTicker({
152	      onTick: (dt) => this.tick(dt),
153	      now: () => this.now(),
154	      ...(setTimer ? { setTimer } : {}),
155	      ...(clearTimer ? { clearTimer } : {})
