164	    // Bandwidth over the window since the last read (not a lifetime average).
165	    const windowTicks = Math.max(1, this.tickCount - this.lastDiagTick);
166	    const windowBytes = this.bytesOut - this.lastDiagBytes;
167	    this.lastDiagTick = this.tickCount;
168	    this.lastDiagBytes = this.bytesOut;
169	    return {
170	      worldId: this.worldId,
171	      players: this.clients.size,
172	      tick: this.tickCount,
173	      slowestTickMs: Math.round(this.slowestTickMs * 100) / 100,
174	      kbOutPerSec: Math.round((windowBytes / 1024 / (windowTicks * TICK_SECONDS)) * 10) / 10
175	    };
176	  }
177	
178	  /** The replay log + world constants (admin-only; drives server/scripts/replay.ts). */
179	  logDump(): RoomLogDump {
