15	 * shares one room per describe where isolation allows.
16	 */
17	
18	type Frame = { kind: "text"; message: ServerMessage } | { kind: "binary"; sync: Promise<WorldSync | null> } | { kind: "close"; code: number };
19	
20	function fakeSink(): ClientSink & { frames: Frame[]; messagesOf<T extends ServerMessage["t"]>(t: T): Array<Extract<ServerMessage, { t: T }>> } {
21	  const frames: Frame[] = [];
22	  return {
23	    frames,
24	    send(data) {
25	      if (typeof data === "string") frames.push({ kind: "text", message: JSON.parse(data) as ServerMessage });
26	      else frames.push({ kind: "binary", sync: gunzipWorldSync(data) });
27	    },
28	    close(code) {
29	      frames.push({ kind: "close", code });
30	    },
31	    bufferedAmount: () => 0,
32	    messagesOf<T extends ServerMessage["t"]>(t: T) {
33	      return frames
34	        .filter((f): f is Extract<Frame, { kind: "text" }> => f.kind === "text")
35	        .map((f) => f.message)
36	        .filter((m): m is Extract<ServerMessage, { t: T }> => m.t === t);
37	    }
38	  };
39	}
40	
41	function claimsFor(id: string, wid: string, role: "owner" | "member" = "member"): TicketClaims {
42	  return { sub: id, wid, name: id.toUpperCase(), skinId: null, role, pv: PROTOCOL_VERSION, iat: 0, exp: 9999999999 };
43	}
44	
45	const move = { forward: false, back: false, left: false, right: false, jump: false, sprint: false, crouch: false };
46	
47	async function makeRoom(worldId = "w1") {
48	  const persistence = createMemoryPersistence();
49	  const record = await persistence.loadWorld(worldId);
50	  const room = new Room(record!, persistence, () => 0);
51	  return { room, persistence };
52	}
