1	import { useCallback, useEffect, useState } from "react";
2	import CreateWorldForm from "@/components/menu/CreateWorldForm";
3	import MenuScreen from "@/components/menu/MenuScreen";
4	import type { Profile } from "@/lib/game/profiles";
5	import { GAME_MODE_PRESETS, type GameMode } from "@/lib/game/gameModes";
6	import { DIFFICULTY_PRESETS, type Difficulty } from "@/lib/game/difficulties";
7	import { createWorld, deleteWorld, MAX_WORLD_NAME, renameWorld, WORLD_TYPE_PRESETS, worldsForProfile } from "@/lib/game/worlds";
8	import type { WorldType } from "@/lib/world";
9	import { onlineUsed } from "@/lib/auth/client";
10	import { createInviteLink, createOnlineWorld, listOnlineWorlds, revokeInviteLinks, type OnlineWorld } from "@/lib/online/onlineClient";
11	import { resolveSeed } from "@/lib/game/worlds";
12	
13	/** Short label for a world type (the default type is left unlabelled on cards). */
14	function worldTypeLabel(id: WorldType): string {
15	  return WORLD_TYPE_PRESETS.find((preset) => preset.id === id)?.label ?? id;
16	}
17	
18	/** Short label for a game mode (survival is left unlabelled on cards). */
19	function gameModeLabel(id: GameMode): string {
20	  return GAME_MODE_PRESETS.find((preset) => preset.id === id)?.label ?? id;
21	}
22	
23	/** Short label for a difficulty (normal is left unlabelled on cards). */
24	function difficultyLabel(id: Difficulty): string {
25	  return DIFFICULTY_PRESETS.find((preset) => preset.id === id)?.label ?? id;
26	}
27	
28	type WorldSelectProps = {
29	  profile: Profile;
30	  /** Enter a world (the shell records last-played and boots it). */
31	  onPlay: (worldId: string) => void;
32	  /** Join an online (server-hosted) world. */
33	  onPlayOnline: (world: OnlineWorld) => void;
34	  /** Back to the profile list. */
35	  onBack: () => void;
36	};
37	
38	/** A profile's world list: pick a world, or create / rename / delete one. */
39	export default function WorldSelect({ profile, onPlay, onPlayOnline, onBack }: WorldSelectProps) {
40	  const [creating, setCreating] = useState(false);
41	  const [creatingOnline, setCreatingOnline] = useState(false);
42	  const [onlineWorlds, setOnlineWorlds] = useState<OnlineWorld[] | null>(null);
43	  const [inviteCopied, setInviteCopied] = useState<string | null>(null);
44	  const [inviteError, setInviteError] = useState<string | null>(null);
45	  const [invitesRevoked, setInvitesRevoked] = useState<string | null>(null);
46	  const [onlineCreateError, setOnlineCreateError] = useState<string | null>(null);
47	
48	  // Online worlds appear only once this browser has used online features —
49	  // offline-first: no fetch, no section, no account until the player opts in.
50	  const refreshOnline = useCallback(() => {
51	    if (onlineUsed()) void listOnlineWorlds().then(setOnlineWorlds);
52	  }, []);
53	  useEffect(() => refreshOnline(), [refreshOnline]);
54	  const [editingId, setEditingId] = useState<string | null>(null);
55	  const [editName, setEditName] = useState("");
56	  const [confirmingDeleteId, setConfirmingDeleteId] = useState<string | null>(null);
57	
58	  if (creating) {
59	    return (
60	      <MenuScreen title={`${profile.name} — New World`}>
61	        <CreateWorldForm
62	          onCreate={(name, seed, worldType, gameMode, difficulty, hardcore) => {
63	            const world = createWorld(profile.id, name, seed, { worldType, gameMode, difficulty, hardcore });
64	            setCreating(false);
65	            onPlay(world.id); // straight into the freshly created world
66	          }}
67	          onCancel={() => setCreating(false)}
68	        />
69	      </MenuScreen>
70	    );
71	  }
72	
73	  if (creatingOnline) {
74	    return (
75	      <MenuScreen title={`${profile.name} — New Online World`}>
76	        {onlineCreateError && <p className="account-error">{onlineCreateError}</p>}
77	        <CreateWorldForm
78	          onCreate={(name, seed, worldType, gameMode, difficulty, hardcore) => {
79	            // Same form, different home: the world row lives on the server and
80	            // the game server hosts it — friends join by invite link.
81	            setOnlineCreateError(null);
82	            void createOnlineWorld({ name, seed: resolveSeed(seed), worldType, gameMode, difficulty, hardcore }).then((world) => {
83	              if (world) {
84	                setCreatingOnline(false);
85	                onPlayOnline(world);
86	              } else {
87	                // Keep the form open so the entered settings aren't lost on a retry.
88	                setOnlineCreateError("Couldn't create the online world — are you signed in and online?");
89	              }
90	            });
91	          }}
92	          onCancel={() => setCreatingOnline(false)}
93	        />
94	      </MenuScreen>
95	    );
96	  }
97	
98	  const worlds = worldsForProfile(profile.id);
99	
100	  return (
101	    <MenuScreen title={`${profile.name} — Worlds`}>
102	      {worlds.length === 0 ? (
103	        <p className="menu-empty">No worlds yet. Create your first world.</p>
104	      ) : (
105	        <ul className="menu-list">
106	          {worlds.map((world) => (
107	            <li key={world.id} className="menu-card">
108	              {editingId === world.id ? (
109	                <form
110	                  className="menu-rename"
111	                  onSubmit={(event) => {
112	                    event.preventDefault();
113	                    renameWorld(world.id, editName);
114	                    setEditingId(null); // re-render re-reads the manifest
115	                  }}
116	                >
117	                  <input
118	                    className="menu-input"
119	                    value={editName}
120	                    maxLength={MAX_WORLD_NAME}
121	                    autoFocus
122	                    aria-label="Rename world"
123	                    onChange={(event) => setEditName(event.target.value)}
124	                  />
125	                  <button type="submit" className="mc-button">
126	                    Save
127	                  </button>
128	                  <button type="button" className="mc-button" onClick={() => setEditingId(null)}>
129	                    Cancel
130	                  </button>
131	                </form>
132	              ) : confirmingDeleteId === world.id ? (
133	                <div className="menu-confirm">
134	                  <span>Delete “{world.name}”? This cannot be undone.</span>
135	                  <div className="menu-confirm-actions">
136	                    <button
137	                      className="mc-button danger"
138	                      onClick={() => {
139	                        deleteWorld(world.id);
140	                        setConfirmingDeleteId(null); // re-render re-reads the manifest
141	                      }}
142	                    >
143	                      Delete
144	                    </button>
145	                    <button className="mc-button" onClick={() => setConfirmingDeleteId(null)}>
146	                      Cancel
147	                    </button>
148	                  </div>
149	                </div>
150	              ) : (
151	                <>
152	                  <button className="menu-card-play" data-testid={`world-${world.id}`} onClick={() => onPlay(world.id)}>
153	                    <span className="menu-card-name">{world.name}</span>
154	                    <span className="menu-card-sub">
155	                      {world.hardcore ? `Hardcore · ` : ""}
156	                      {world.gameMode !== "survival" ? `${gameModeLabel(world.gameMode)} · ` : ""}
157	                      {!world.hardcore && world.difficulty !== "normal" ? `${difficultyLabel(world.difficulty)} · ` : ""}
158	                      {world.worldType !== "default" ? `${worldTypeLabel(world.worldType)} · ` : ""}Seed {world.seed}
159	                    </span>
160	                  </button>
161	                  <div className="menu-card-actions">
162	                    <button
163	                      className="mc-button"
164	                      onClick={() => {
165	                        setEditName(world.name);
166	                        setEditingId(world.id);
167	                      }}
168	                    >
169	                      Rename
170	                    </button>
171	                    <button className="mc-button" onClick={() => setConfirmingDeleteId(world.id)}>
172	                      Delete
173	                    </button>
174	                  </div>
175	                </>
176	              )}
177	            </li>
178	          ))}
179	        </ul>
180	      )}
181	      {onlineWorlds !== null && (
182	        <section className="menu-online">
183	          <h3 className="menu-online-title">Online Worlds</h3>
184	          {onlineWorlds.length === 0 ? (
185	            <p className="menu-empty">No online worlds yet — create one and share the invite link.</p>
186	          ) : (
187	            <ul className="menu-list">
188	              {onlineWorlds.map((world) => (
189	                <li key={world.id} className="menu-card">
190	                  <button className="menu-card-play" data-testid={`online-world-${world.id}`} onClick={() => onPlayOnline(world)}>
191	                    <span className="menu-card-name">{world.name}</span>
192	                    <span className="menu-card-sub">
193	                      {world.role === "owner" ? "Your world" : "Joined"} · Seed {world.seed}
194	                    </span>
195	                  </button>
196	                  {world.role === "owner" && (
197	                    <div className="menu-card-actions">
198	                      <button
199	                        className="mc-button"
200	                        onClick={() => {
201	                          setInvitesRevoked(null);
202	                          setInviteError(null);
203	                          setInviteCopied(null);
204	                          void createInviteLink(world.id).then((link) => {
205	                            const clipboard = navigator.clipboard;
206	                            // Mint failure (offline/auth) or no clipboard: report it, don't lie.
207	                            if (!link || !clipboard) return void setInviteError(world.id);
208	                            // Only claim "copied" once the write actually resolves (it can reject, e.g. no focus).
209	                            void clipboard
210	                              .writeText(link)
211	                              .then(() => setInviteCopied(world.id))
212	                              .catch(() => setInviteError(world.id));
213	                          });
214	                        }}
215	                      >
216	                        {inviteError === world.id ? "Copy failed" : inviteCopied === world.id ? "Link copied!" : "Copy invite"}
217	                      </button>
