219	                        className="mc-button"
220	                        title="Invalidate every invite link you've shared for this world"
221	                        onClick={() => {
222	                          setInviteCopied(null);
223	                          setInviteError(null);
224	                          void revokeInviteLinks(world.id).then((count) => {
225	                            if (count !== null) setInvitesRevoked(world.id);
226	                          });
227	                        }}
228	                      >
229	                        {invitesRevoked === world.id ? "Links revoked" : "Revoke links"}
230	                      </button>
231	                    </div>
232	                  )}
233	                </li>
234	              ))}
235	            </ul>
236	          )}
