/* Profile- and world-selection menus (the GameShell screens before play).
   Reuses the .mc-button bevel and the .pause-skins swatch grid from hud.css. */

.menu-screen {
  position: fixed;
  inset: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: linear-gradient(180deg, #2a2d3a 0%, #15171f 100%);
  animation: mc-fade-in 140ms ease-out;
}

.menu-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(94vw, 420px);
  max-height: 88vh;
}

.menu-logo {
  text-align: center;
  color: var(--mc-text-light);
  font-size: 30px;
  font-weight: 700;
  letter-spacing: 1px;
  text-shadow: var(--mc-text-shadow);
}

.menu-title {
  text-align: center;
  color: var(--mc-text-light);
  font-size: 15px;
  font-weight: 700;
  opacity: 0.85;
  text-shadow: var(--mc-text-shadow);
  margin-bottom: 6px;
}

.menu-empty {
