// Tiny protocol-version probe: send a hello with the given protocol + a bogus
// ticket, report the close code. v2 server: protocol 2 -> 4000 (bad ticket),
// protocol 1 -> 4001 (protocol mismatch). v1 server: the reverse.
const url = "wss://monecraft-server.fly.dev/ws";
const proto = Number(process.argv[2] ?? 2);
const ws = new WebSocket(url);
ws.binaryType = "arraybuffer";
const timer = setTimeout(() => { console.log(`proto=${proto} TIMEOUT`); process.exit(1); }, 12000);
ws.onopen = () => ws.send(JSON.stringify({ t: "hello", ticket: "bogus-ticket", protocol: proto }));
ws.onmessage = (e) => console.log(`proto=${proto} MESSAGE`, typeof e.data === "string" ? e.data.slice(0, 60) : "[binary]");
ws.onclose = (e) => { clearTimeout(timer); console.log(`proto=${proto} CLOSE code=${e.code} reason="${e.reason}"`); process.exit(0); };
ws.onerror = () => {};
EOF
